package sakura.world

import sakura.ThreeInterop
import vendor.three.*

import scala.scalajs.js

/** Whole-world parity for `WorldIndex` against `/tmp/upstream-oracle/world-index-oracle.json`.
  *
  * The oracle runs upstream's own `world/index.js` -- the body of `buildWorld` is executed
  * verbatim, with only the district list trimmed to the chunks that are ported -- so the
  * expectations here carry no transcription of mine: the rows are the numbers three 0.185.1
  * produced, and the authored-layout expectations are upstream's own literals, keyed the way
  * the JavaScript writes them.
  *
  * A child row is (meshCount, instancedCount, vertexCount, multiMatCount, groupSliceCount,
  * castShadowCount, receiveShadowCount, bbox, colorDigest); bounding boxes are each mesh's
  * local AABB transformed by its `matrixWorld` and unioned, which is what `Box3.setFromObject`
  * measures. Rows are compared as text so a mismatch reports both sides.
  */
class WorldIndexParitySuite extends munit.FunSuite:

  override def beforeAll(): Unit = WorldCanvasStub.install()

  final private case class Traced(
    meshCount: Int,
    instancedCount: Int,
    vertexCount: Int,
    multiMatCount: Int,
    groupSliceCount: Int,
    castShadowCount: Int,
    receiveShadowCount: Int,
    bbox: Vector[Double],
    colorDigest: Vector[Int]
  )

  private def round3(value: Double): Double = math.round(value * 1000.0) / 1000.0

  private def traceChild(child: Object3D[?]): Traced =
    child.updateMatrixWorld(js.defined(true))
    var meshCount          = 0
    var instancedCount     = 0
    var vertexCount        = 0
    var multiMatCount      = 0
    var groupSliceCount    = 0
    var castShadowCount    = 0
    var receiveShadowCount = 0
    val colors             = scala.collection.mutable.ArrayBuffer.empty[Int]
    val min                = Array(Double.PositiveInfinity, Double.PositiveInfinity, Double.PositiveInfinity)
    val max                = Array(Double.NegativeInfinity, Double.NegativeInfinity, Double.NegativeInfinity)
    child.traverse { (node: Object3D[Object3DEventMap]) =>
      if ThreeInterop.isMesh(node) then
        meshCount += 1
        ThreeInterop.asInstancedObject(node).foreach(instanced => instancedCount += instanced.count.toInt)
        vertexCount += ThreeInterop.positionCount(node.asInstanceOf[Mesh[?, ?, ?]].geometry).toInt
        ThreeInterop.asMesh(node).foreach { mesh =>
          val geometry = ThreeInterop.meshGeometry(mesh)
          groupSliceCount += geometry.groups.length
          materialColorsOf(mesh).take(8 - colors.length).foreach(colors += _)
          if colors.length > 8 then colors.remove(8, colors.length - 8)
          multiMatCount += (if hasMaterialArray(mesh) then 1 else 0)
        }
        if node.castShadow then castShadowCount += 1
        if node.receiveShadow then receiveShadowCount += 1
        ThreeInterop.asMesh(node).foreach { mesh =>
          val geometry  = ThreeInterop.meshGeometry(mesh)
          val matrix    = ThreeInterop.matrixElements(node.matrixWorld)
          val position  = ThreeInterop.attributeDoubles(geometry, "position")
          var localMinX = Double.PositiveInfinity
          var localMinY = Double.PositiveInfinity
          var localMinZ = Double.PositiveInfinity
          var localMaxX = Double.NegativeInfinity
          var localMaxY = Double.NegativeInfinity
          var localMaxZ = Double.NegativeInfinity
          var index     = 0
          val count     = position.length / 3
          while index < count do
            val x = position(index * 3)
            val y = position(index * 3 + 1)
            val z = position(index * 3 + 2)
            if x < localMinX then localMinX = x
            if x > localMaxX then localMaxX = x
            if y < localMinY then localMinY = y
            if y > localMaxY then localMaxY = y
            if z < localMinZ then localMinZ = z
            if z > localMaxZ then localMaxZ = z
            index += 1
          /* The oracle measures as three's `Box3.setFromObject` does: each mesh's local
           * axis-aligned box is transformed and unioned, so a rotated part reads as the box
           * its box sweeps out rather than as its own vertex extent. */
          Vector(localMinX, localMaxX).foreach { x =>
            Vector(localMinY, localMaxY).foreach { y =>
              Vector(localMinZ, localMaxZ).foreach { z =>
                val worldX = matrix(0) * x + matrix(4) * y + matrix(8) * z + matrix(12)
                val worldY = matrix(1) * x + matrix(5) * y + matrix(9) * z + matrix(13)
                val worldZ = matrix(2) * x + matrix(6) * y + matrix(10) * z + matrix(14)
                if worldX < min(0) then min(0) = worldX
                if worldX > max(0) then max(0) = worldX
                if worldY < min(1) then min(1) = worldY
                if worldY > max(1) then max(1) = worldY
                if worldZ < min(2) then min(2) = worldZ
                if worldZ > max(2) then max(2) = worldZ
              }
            }
          }
        }
    }
    val bbox =
      if min(0).isInfinite then Vector.empty
      else
        Vector(round3(min(0)), round3(min(1)), round3(min(2)),
          round3(max(0)), round3(max(1)), round3(max(2)))
    Traced(meshCount, instancedCount, vertexCount, multiMatCount, groupSliceCount,
      castShadowCount, receiveShadowCount, bbox, colors.toVector.take(8))
  end traceChild

  private def materialColorsOf(mesh: Mesh[?, ?, ?]): Vector[Int] =
    mesh.material match
      case materials: js.Array[Material[?]] =>
        materials.toVector.collect {
          case material: MeshBasicMaterial => material.color.getHex().toInt
          case material: MeshToonMaterial  => material.color.getHex().toInt
        }
      case material: MeshBasicMaterial => Vector(material.color.getHex().toInt)
      case material: MeshToonMaterial  => Vector(material.color.getHex().toInt)
      case _                           => Vector.empty

  private def hasMaterialArray(mesh: Mesh[?, ?, ?]): Boolean =
    mesh.material match
      case _: js.Array[Material[?]] => true
      case _                        => false

  /** Compares the trace child by child.
    *
    * Counts, colours, group slices and shadow flags are exact. Bounding boxes are compared at
    * the precision the oracle prints them -- three decimals -- because that is all the recorded
    * measurement carries: a corner whose last bit differs between V8's `Math.sin` and the JVM's
    * moves the printed value by one unit in that last place and nothing else about the object.
    */
  private def rowMismatches(traced: Vector[Traced]): Vector[String] =
    traced.zip(AllRows).zipWithIndex.collect {
      case ((row, want), index) if !rowMatches(row, want) =>
        s"child[$index]\n  got ${renderRow(row)}\n  exp $want"
    }.take(6)

  private def rowMatches(row: Traced, want: String): Boolean =
    val fields = want.split("\\|")
    if fields.length != 3 then false
    else
      val counts = Vector(row.meshCount, row.instancedCount, row.vertexCount, row.multiMatCount,
        row.groupSliceCount, row.castShadowCount, row.receiveShadowCount).mkString(",")
      val colors = row.colorDigest.mkString(",")
      lazy val bboxOk = fields(1).split(",").map(_.toDouble).zip(row.bbox)
        .forall((theirs, mine) => math.abs(theirs - mine) <= 0.001 + 1e-9)
      counts == fields(0) && colors == fields(2) && bboxOk

  private def renderDouble(value: Double): String =
    if value == 0.0 then "0.0"
    else if value == value.toLong.toDouble then s"${value.toLong}.0"
    else value.toString

  private def renderBbox(bbox: Vector[Double]): String = bbox.map(renderDouble).mkString(",")

  private def renderRow(traced: Traced): String =
    val counts = Vector(traced.meshCount, traced.instancedCount, traced.vertexCount,
      traced.multiMatCount, traced.groupSliceCount, traced.castShadowCount,
      traced.receiveShadowCount).mkString(",")
    s"$counts|${renderBbox(traced.bbox)}|${traced.colorDigest.mkString(",")}"

  private def pairString(fields: Vector[(String, String)]): String =
    fields.sortBy(_._1).map((key, value) => s"$key=$value").mkString(" ")

  private def renderFace(face: Buildings.Face): String = face match
    case Buildings.Face.XMinus => "x-"
    case Buildings.Face.XPlus  => "x+"
    case Buildings.Face.ZMinus => "z-"
    case Buildings.Face.ZPlus  => "z+"

  private def renderRoofKind(kind: Buildings.RoofKind): String = kind match
    case Buildings.RoofKind.Gable => "gable"
    case Buildings.RoofKind.Hip   => "hip"
    case Buildings.RoofKind.Shed  => "shed"
    case Buildings.RoofKind.Flat  => "flat"

  private def renderHouse(plot: HouseDef): String =
    val required = Vector(
      "x"      -> renderDouble(plot.x),
      "z"      -> renderDouble(plot.z),
      "w"      -> renderDouble(plot.w),
      "d"      -> renderDouble(plot.d),
      "face"   -> renderFace(plot.face),
      "floors" -> plot.floors.toString,
      "seed"   -> plot.seed.toString
    )
    val optional = Vector(
      "wall"           -> Some(plot.wall.toString),
      "roof"           -> Some(plot.roof.toString),
      "roofKind"       -> Some(renderRoofKind(plot.roofKind)),
      "postBoxOut"     -> plot.postBoxOut.map(renderDouble),
      "postBoxSink"    -> plot.postBoxSink.map(renderDouble),
      "postBoxAlong"   -> plot.postBoxAlong.map(renderDouble),
      "gomiSink"       -> plot.gomiSink.map(renderDouble),
      "gomiOut"        -> plot.gomiOut.map(renderDouble),
      "gomiSignAlong"  -> plot.gomiSignAlong.map(renderDouble),
      "planterAlong"   -> plot.planterAlong.map(renderDouble),
      "planterOut"     -> plot.planterOut.map(renderDouble),
      "planterSpacing" -> plot.planterSpacing.map(renderDouble),
      "planterSink"    -> plot.planterSink.map(renderDouble),
      "umbrellaSink"   -> plot.umbrellaSink.map(renderDouble),
      "bikeOut"        -> plot.bikeOut.map(renderDouble),
      "bikeLift"       -> plot.bikeLift.map(renderDouble),
      "skipBike"       -> Option.when(plot.skipBike)("true")
    ).collect { case (key, Some(value)) => key -> value }
    pairString(required ++ optional)
  end renderHouse

  private def renderWall(spec: WallSpec): String =
    val kind = spec.kind match
      case WallKind.Mesh   => Vector.empty
      case WallKind.Timber => Vector("kind" -> "timber")
      case WallKind.Block  => Vector("kind" -> "block")
    pairString(Vector("x" -> renderDouble(spec.x), "z"      -> renderDouble(spec.z),
      "len"               -> renderDouble(spec.len), "axis" -> "z", "h" -> renderDouble(spec.h)) ++ kind ++
      spec.fence.map(fence => "fence" -> fence.toString))

  private def renderPole(pole: PoleDef): String =
    pairString(Vector("x" -> renderDouble(pole.x), "z"    -> renderDouble(pole.z),
      "h"                 -> renderDouble(pole.h), "seed" -> pole.seed.toString,
      "armDir"            -> renderDouble(pole.armDir)) ++
      Option.when(pole.lamp)("lamp" -> "true") ++
      pole.baseSink.map(sink => "baseSink" -> renderDouble(sink)) ++
      Option.when(!pole.transformer)("transformer" -> "false"))

  private def renderSakura(spot: SakuraSpot): String =
    pairString(Vector("x" -> renderDouble(spot.x), "z"        -> renderDouble(spot.z),
      "scale"             -> renderDouble(spot.scale), "seed" -> spot.seed.toString,
      "lean"              -> renderDouble(spot.lean)) ++
      spot.leanDir.map(dir => "leanDir" -> renderDouble(dir)))

  private def renderShrub(spot: ShrubSpot): String =
    pairString(Vector("x" -> renderDouble(spot.x), "z"         -> renderDouble(spot.z),
      "y"                 -> renderDouble(spot.y), "r"         -> renderDouble(spot.r), "count" -> spot.count.toString,
      "spread"            -> renderDouble(spot.spread), "seed" -> spot.seed.toString))

  private def renderPlanter(spot: PlanterSpot): String =
    pairString(Vector("x" -> renderDouble(spot.x), "z"      -> renderDouble(spot.z),
      "r"                 -> renderDouble(spot.r), "flower" -> spot.flower.toString))

  /** Renders a number the way JavaScript's own `Array.join` does: `1`, not `1.0`. */
  private def renderJs(value: Double): String =
    if value == 0.0 then "0"
    else if value == value.toLong.toDouble then value.toLong.toString
    else value.toString

  private def renderCollider(box: Collider): String =
    Vector(round3(box.x0), round3(box.z0), round3(box.x1), round3(box.z1), round3(box.top),
      box.bottom.fold(Double.NaN)(round3)).map(value =>
      if value.isNaN then "" else renderJs(value)
    ).mkString(",")

  private def renderPlatform(box: Platform): String =
    Vector(box.x0, box.x1, box.z0, box.z1, box.top).map(value => renderJs(round3(value))).mkString(",")

  /** The first few indices where a rendered vector differs, so one run names the culprit. */
  private def mismatchAt(actual: Vector[String], expected: Vector[String], where: String): Vector[String] =
    actual.zip(expected).zipWithIndex.collect {
      case ((got, want), index) if got != want => s"$where[$index] $got != $want"
    }.take(6)

  private def mismatchAtCounts(actual: Vector[Int], expected: Vector[Int], where: String): Vector[String] =
    mismatchAt(actual.map(_.toString), expected.map(_.toString), where)

  private def assertData[T](actual: Vector[T], expected: Vector[String], render: T => String, where: String): Unit =
    assertEquals(actual.map(render), expected, where)

  /** One build for the whole suite: assembling the world bakes the planet, so four builds
    * would spend a minute re-deriving the same geometry.
    */
  private lazy val builtWorld: WorldIndex.World = WorldIndex.buildWorld(new Scene())

  test("the authored layout data matches the upstream literals") {
    assertData(WorldIndex.houseDefs, ExpectedHouses, renderHouse, "house definitions")
    assertData(WorldIndex.wallSpecs, ExpectedWalls, renderWall, "garden boundaries")
    assertData(WorldIndex.poleDefs, ExpectedPoles, renderPole, "utility poles")
    assertData(WorldIndex.baseSakuraSpots, ExpectedSakura, renderSakura, "cherry trees")
    assertData(WorldIndex.baseShrubSpots, ExpectedShrubs, renderShrub, "shrub clumps")
    assertData(WorldIndex.planterSpots, ExpectedPlanters, renderPlanter, "street planters")
  }

  test("the assembled world matches the upstream structural trace") {
    val children = builtWorld.root.children.toVector
    val traced   = children.map(traceChild)
    val problems = scala.collection.mutable.ArrayBuffer.empty[String]

    val totals = traced.foldLeft((0, 0, 0, 0, 0, 0, 0)) { (acc, row) =>
      (acc._1 + row.meshCount, acc._2 + row.instancedCount, acc._3 + row.vertexCount,
        acc._4 + row.multiMatCount, acc._5 + row.groupSliceCount, acc._6 + row.castShadowCount,
        acc._7 + row.receiveShadowCount)
    }
    val totalRow = Vector(totals._1, totals._2, totals._3, totals._4, totals._5, totals._6,
      totals._7).mkString(",")
    if children.length != TopChildCount then
      problems += s"top children ${children.length} != $TopChildCount"
    if totalRow != TotalRow then problems += s"world totals $totalRow != $TotalRow"
    val rootBbox = renderBbox(traceChild(builtWorld.root).bbox)
    if rootBbox != RootBbox then problems += s"world bbox $rootBbox != $RootBbox"

    if children.length == TopChildCount then
      problems ++= rowMismatches(traced)
      /* A census over every child, so a deviation inside a district still names the index: the
       * digests above prove the district's interior, this says which child moved. */
      problems ++= mismatchAtCounts(traced.map(_.vertexCount), ChildVertexCounts, "vertex count")
      problems ++= mismatchAtCounts(traced.map(_.meshCount), ChildMeshCounts, "mesh count")

    if problems.nonEmpty then fail(problems.mkString("\n"))
  }

  test("the world registries match the upstream assembly") {
    val built    = builtWorld
    val problems = scala.collection.mutable.ArrayBuffer.empty[String]

    if built.colliders.length != ColliderCount then
      problems += s"collider count ${built.colliders.length} != $ColliderCount"
    else problems ++= mismatchAt(built.colliders.map(renderCollider), ColliderRows, "collider")
    if built.platforms.length != PlatformCount then
      problems += s"platform count ${built.platforms.length} != $PlatformCount"
    else problems ++= mismatchAt(built.platforms.map(renderPlatform), PlatformRows, "platform")
    if built.cuts.length != CutCount then
      problems += s"cut count ${built.cuts.length} != $CutCount"
    if built.interactables.map(_.label) != InteractableLabels then
      problems += s"interactables ${built.interactables.map(_.label).mkString("|")}"

    if problems.nonEmpty then fail(problems.mkString("\n"))
  }

  test("the planet bake and the ground query match upstream") {
    val built = builtWorld
    val bake  = built.bakeStats
    assertEquals(Vector(bake.wrapped, bake.instanced, bake.rigid, bake.tris).mkString(","), Bake,
      "bake stats")
    HeightProbes.foreach { (x, z, plain, fromGround, fromHigh, fromBelow) =>
      assertEqualsDouble(round3(built.heightAt(x, z)), plain, 1e-9, s"heightAt($x, $z)")
      assertEqualsDouble(round3(built.heightAt(x, z, Some(0.0))), fromGround, 1e-9,
        s"heightAt($x, $z) from 0.0")
      assertEqualsDouble(round3(built.heightAt(x, z, Some(5.0))), fromHigh, 1e-9,
        s"heightAt($x, $z) from 5.0")
      assertEqualsDouble(round3(built.heightAt(x, z, Some(-6.0))), fromBelow, 1e-9,
        s"heightAt($x, $z) from -6.0")
    }
  }

  private lazy val AllRows: Vector[String] =
